+package com.finboost.bank.statement.parser.service.document.extraction.local;
+
+import com.finboost.bank.statement.parser.representation.document.extraction.*;
+import org.apache.pdfbox.Loader;
+import org.apache.pdfbox.pdmodel.PDDocument;
+import org.apache.pdfbox.pdmodel.PDPage;
+import org.apache.pdfbox.text.PDFTextStripper;
+import org.apache.pdfbox.text.TextPosition;
+import org.springframework.stereotype.Service;
+
+import java.io.File;
+import java.io.IOException;
+import java.util.*;
+import java.util.regex.Pattern;
+import java.util.stream.Collectors;
+
+@Service
+public class PdfBoxNativeDocumentExtractionService implements NativeDocumentExtractionService {
+
+    private static final float POINTS_PER_INCH = 72f;
+    private static final Pattern DATE = Pattern.compile("^(?:\\d{1,2}[-/.]){2}(?:\\d{2}|\\d{4})(?:\\s.*)?$");
+    private static final Set<String> FOOTERS = Set.of("closing balance", "total", "page ", "statement summary");
+
+    @Override
+    public Optional<DocumentExtractionResult> extract(File statementFile, NativeTablePolicy policy) throws IOException {
+        try (PDDocument pdf = Loader.loadPDF(statementFile)) {
+            Map<Integer, Page> pages = new LinkedHashMap<>();
+            int transactionRows = 0;
+            int wordIndex = 1;
+
+            for (int pageIndex = 0; pageIndex < pdf.getNumberOfPages(); pageIndex++) {
+                PDPage pdfPage = pdf.getPage(pageIndex);
+                PositionStripper stripper = new PositionStripper(pageIndex + 1);
+                stripper.setStartPage(pageIndex + 1);
+                stripper.setEndPage(pageIndex + 1);
+                String content = stripper.getText(pdf);
+                List<Word> words = toWords(stripper.positions(), pageIndex + 1, wordIndex);
+                wordIndex += words.size();
+
+                List<List<Word>> lines = groupLines(words);
+                Optional<Header> header = findHeader(lines);
+                Map<Integer, Table> tables = new LinkedHashMap<>();
+                if (header.isPresent()) {
+                    Table table = buildTable(lines, header.get(), pageIndex + 1, policy);
+                    transactionRows += countTransactionRows(table);
+                    if (table.getTotalRows() > 1) {
+                        tables.put(0, table);
+                    }
+                }
+
+                Page page = new Page();
+                page.setPageNumber(pageIndex + 1);
+                page.setWidth((double) (pdfPage.getCropBox().getWidth() / POINTS_PER_INCH));
+                page.setHeight((double) (pdfPage.getCropBox().getHeight() / POINTS_PER_INCH));
+                page.setWords(words);
+                page.setContent(content);
+                page.setTables(tables);
+                pages.put(pageIndex + 1, page);
+            }
+
+            if (transactionRows < 2 || pages.values().stream().noneMatch(page -> !page.getTables().isEmpty())) {
+                return Optional.empty();
+            }
+
+            DocumentExtractionResult result = new DocumentExtractionResult();
+            result.setPages(pages);
+            result.setNoOfPages(pages.size());
+            result.setNativeTablePolicy(policy);
+            return Optional.of(result);
+        }
+    }
+
+    private List<Word> toWords(List<TextPosition> positions, int pageNumber, int firstWordIndex) {
+        List<List<TextPosition>> lines = new ArrayList<>();
+        positions.stream()
+                .filter(position -> !position.getUnicode().isBlank())
+                .sorted(Comparator.comparing(TextPosition::getYDirAdj).thenComparing(TextPosition::getXDirAdj))
+                .forEach(position -> {
+                    List<TextPosition> line = lines.stream()
+                            .filter(candidate -> Math.abs(candidate.get(0).getYDirAdj() - position.getYDirAdj()) <= 2.5f)
+                            .findFirst().orElseGet(() -> {
+                                List<TextPosition> created = new ArrayList<>();
+                                lines.add(created);
+                                return created;
+                            });
+                    line.add(position);
+                });
+
+        List<Word> words = new ArrayList<>();
+        int nextWordIndex = firstWordIndex;
+        for (List<TextPosition> line : lines) {
+            line.sort(Comparator.comparing(TextPosition::getXDirAdj));
+            List<TextPosition> current = new ArrayList<>();
+            for (TextPosition position : line) {
+                if (!current.isEmpty()) {
+                    TextPosition previous = current.get(current.size() - 1);
+                    float gap = position.getXDirAdj() - (previous.getXDirAdj() + previous.getWidthDirAdj());
+                    if (gap > Math.max(1.5f, previous.getWidthOfSpace() * .55f)) {
+                        words.add(toWord(current, pageNumber, nextWordIndex++));
+                        current.clear();
+                    }
+                }
+                current.add(position);
+            }
+            if (!current.isEmpty()) {
+                words.add(toWord(current, pageNumber, nextWordIndex++));
+            }
+        }
+        return words;
+    }
+
+    private Word toWord(List<TextPosition> positions, int pageNumber, int wordIndex) {
+        TextPosition first = positions.get(0);
+        float x1 = first.getXDirAdj() / POINTS_PER_INCH;
+        float y1 = first.getYDirAdj() / POINTS_PER_INCH;
+        float x2 = positions.stream().map(position -> position.getXDirAdj() + position.getWidthDirAdj())
+                .max(Float::compareTo).orElse(first.getXDirAdj()) / POINTS_PER_INCH;
+        float y2 = (first.getYDirAdj() + positions.stream().map(TextPosition::getHeightDir).max(Float::compareTo).orElse(0f)) / POINTS_PER_INCH;
+        String text = positions.stream().map(TextPosition::getUnicode).collect(Collectors.joining());
+        return new Word(text, x1, y1, x2, y1, x2, y2, x1, y2, pageNumber, x2 - x1, y2 - y1,
+                pageNumber, wordIndex);
+    }
+
+    private List<List<Word>> groupLines(List<Word> words) {
+        List<List<Word>> lines = new ArrayList<>();
+        words.stream().sorted(Comparator.comparing(Word::getY1).thenComparing(Word::getX1)).forEach(word -> {
+            List<Word> line = lines.stream()
+                    .filter(candidate -> Math.abs(candidate.get(0).getY1() - word.getY1()) <= .04f)
+                    .findFirst().orElseGet(() -> {
+                        List<Word> created = new ArrayList<>();
+                        lines.add(created);
+                        return created;
+                    });
+            line.add(word);
+        });
+        lines.forEach(line -> line.sort(Comparator.comparing(Word::getX1)));
+        return lines;
+    }
+
+    private Optional<Header> findHeader(List<List<Word>> lines) {
+        for (int index = 0; index < lines.size(); index++) {
+            List<Word> combined = new ArrayList<>(lines.get(index));
+            if (index + 1 < lines.size() && Math.abs(lines.get(index + 1).get(0).getY1() - lines.get(index).get(0).getY1()) < .35f) {
+                combined.addAll(lines.get(index + 1));
+            }
+            List<Float> anchors = headerAnchors(combined);
+            if (anchors.size() >= 4 && hasHeader(combined, "date") && hasHeader(combined, "balance")) {
+                return Optional.of(new Header(index, anchors));
+            }
+        }
+        return Optional.empty();
+    }
+
+    private List<Float> headerAnchors(List<Word> words) {
+        Map<String, Float> anchors = new HashMap<>();
+        for (Word word : words) {
+            String value = word.getContent().toLowerCase(Locale.ROOT).replaceAll("[^a-z]", "");
+            if (value.contains("date")) anchors.merge("date" + (anchors.containsKey("date") ? "2" : ""), word.getX1(), Math::min);
+            if (containsAny(value, "narration", "description", "particular", "details", "remarks")) anchors.putIfAbsent("description", word.getX1());
+            if (containsAny(value, "cheque", "chq", "reference", "refno")) anchors.putIfAbsent("reference", word.getX1());
+            if (containsAny(value, "withdraw", "debit", "dramount")) anchors.putIfAbsent("debit", word.getX1());
+            if (containsAny(value, "deposit", "credit", "cramount")) anchors.putIfAbsent("credit", word.getX1());
+            if (value.equals("amount")) anchors.putIfAbsent("amount", word.getX1());
+            if (value.contains("balance")) anchors.putIfAbsent("balance", word.getX1());
+        }
+        return anchors.values().stream().distinct().sorted().collect(Collectors.toList());
+    }
+
+    private boolean hasHeader(List<Word> words, String token) {
+        return words.stream().anyMatch(word -> word.getContent().toLowerCase(Locale.ROOT).contains(token));
+    }
+
+    private boolean containsAny(String value, String... candidates) {
+        return Arrays.stream(candidates).anyMatch(value::contains);
+    }
+
+    private Table buildTable(List<List<Word>> lines, Header header, int pageNumber, NativeTablePolicy policy) {
+        List<Float> anchors = header.anchors();
+        List<Float> boundaries = new ArrayList<>();
+        for (int index = 1; index < anchors.size(); index++) {
+            boundaries.add((anchors.get(index - 1) + anchors.get(index)) / 2f);
+        }
+
+        Map<Integer, Map<Integer, TableCell>> rows = new LinkedHashMap<>();
+        int rowIndex = 0;
+        boolean foundTransaction = false;
+        for (int lineIndex = header.lineIndex(); lineIndex < lines.size(); lineIndex++) {
+            List<Word> line = lines.get(lineIndex);
+            String lineText = line.stream().map(Word::getContent).collect(Collectors.joining(" ")).trim().toLowerCase(Locale.ROOT);
+            boolean dateRow = line.stream().anyMatch(word -> DATE.matcher(word.getContent().trim()).matches());
+            if (lineIndex > header.lineIndex() && FOOTERS.stream().anyMatch(lineText::startsWith)) {
+                break;
+            }
+            if (lineIndex > header.lineIndex() && policy == NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED && !foundTransaction && !dateRow) {
+                continue;
+            }
+            foundTransaction |= dateRow;
+            if (lineIndex > header.lineIndex() && !foundTransaction) {
+                continue;
+            }
+
+            Map<Integer, List<Word>> columnWords = new LinkedHashMap<>();
+            for (Word word : line) {
+                int column = 0;
+                float center = (word.getX1() + word.getX2()) / 2f;
+                while (column < boundaries.size() && center > boundaries.get(column)) column++;
+                columnWords.computeIfAbsent(column, ignored -> new ArrayList<>()).add(word);
+            }
+            Map<Integer, TableCell> cells = new LinkedHashMap<>();
+            for (int column = 0; column < anchors.size(); column++) {
+                cells.put(column, cell(columnWords.getOrDefault(column, List.of()), rowIndex, column, line, boundaries, column));
+            }
+            rows.put(rowIndex++, cells);
+        }
+
+        Table table = new Table();
+        table.setPageNumber(pageNumber);
+        table.setCells(rows);
+        table.setTotalRows(rows.size());
+        table.setTotalColumns(anchors.size());
+        table.setColType(new ArrayList<>());
+        table.setTxnColType(new ArrayList<>());
+        table.setColumnBoundaries(boundaries);
+        if (!rows.isEmpty()) {
+            List<Word> allWords = rows.values().stream().flatMap(row -> row.values().stream()).flatMap(cell -> cell.getWords().stream()).toList();
+            if (!allWords.isEmpty()) {
+                table.setX1(allWords.stream().map(Word::getX1).min(Float::compareTo).orElse(0f));
+                table.setY1(allWords.stream().map(Word::getY1).min(Float::compareTo).orElse(0f));
+                table.setX2(allWords.stream().map(Word::getX2).max(Float::compareTo).orElse(0f));
+                table.setY2(table.getY1());
+                table.setX3(table.getX2());
+                table.setY3(allWords.stream().map(Word::getY3).max(Float::compareTo).orElse(0f));
+                table.setX4(table.getX1());
+                table.setY4(table.getY3());
+            }
+        }
+        return table;
+    }
+
+    private TableCell cell(List<Word> words, int row, int column, List<Word> line, List<Float> boundaries, int boundaryIndex) {
+        TableCell cell = new TableCell();
+        cell.setRowindex(row);
+        cell.setColindex(column);
+        cell.setRowspan(1);
+        cell.setColspan(1);
+        cell.setWords(new ArrayList<>(words));
+        float y1 = line.stream().map(Word::getY1).min(Float::compareTo).orElse(0f);
+        float y2 = line.stream().map(Word::getY3).max(Float::compareTo).orElse(y1);
+        float x1 = boundaryIndex == 0 ? 0f : boundaries.get(boundaryIndex - 1);
+        float x2 = boundaryIndex >= boundaries.size() ? line.stream().map(Word::getX2).max(Float::compareTo).orElse(x1) : boundaries.get(boundaryIndex);
+        cell.setX1(x1); cell.setY1(y1); cell.setX2(x2); cell.setY2(y1);
+        cell.setX3(x2); cell.setY3(y2); cell.setX4(x1); cell.setY4(y2);
+        return cell;
+    }
+
+    private int countTransactionRows(Table table) {
+        return (int) table.getCells().values().stream()
+                .filter(row -> row.values().stream().flatMap(cell -> cell.getWords().stream())
+                        .anyMatch(word -> DATE.matcher(word.getContent().trim()).matches()))
+                .count();
+    }
+
+    private record Header(int lineIndex, List<Float> anchors) { }
+
+    private static class PositionStripper extends PDFTextStripper {
+        private final List<TextPosition> positions = new ArrayList<>();
+
+        PositionStripper(int pageNumber) throws IOException {
+            setSortByPosition(true);
+        }
+
+        @Override
+        protected void writeString(String text, List<TextPosition> textPositions) {
+            positions.addAll(textPositions);
+        }
+
+        List<TextPosition> positions() {
+            return positions;
+        }
+    }
+}
