+package com.finboost.bank.statement.parser.service.document.extraction.local;
+
+import com.finboost.bank.statement.parser.representation.document.extraction.DocumentExtractionResult;
+import com.finboost.bank.statement.parser.representation.document.extraction.NativeTablePolicy;
+import org.junit.jupiter.api.Test;
+
+import java.io.File;
+import java.util.Optional;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+class NativeDocumentExtractionServiceTest {
+
+    private final PdfBoxNativeDocumentExtractionService service = new PdfBoxNativeDocumentExtractionService();
+    private final NativeTablePolicySelector selector = new NativeTablePolicySelector();
+
+    @Test
+    void selectsPoliciesOnlyForKnownStatementFamilies() {
+        assertEquals(NativeTablePolicy.BORDERED_GRID, selector.select("ICICI").orElseThrow());
+        assertEquals(NativeTablePolicy.BOX_GUIDED, selector.select("Standard Chartered").orElseThrow());
+        assertEquals(NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED, selector.select("HDFC").orElseThrow());
+        assertTrue(selector.select("UNKNOWN_BANK").isEmpty());
+    }
+
+    @Test
+    void extractsStructuredRowsFromElectronicFixture() throws Exception {
+        File fixture = new File("src/test/resources/pdf-samples-latest/HDFC/format1.pdf");
+
+        Optional<DocumentExtractionResult> extracted = service.extract(fixture, NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED);
+
+        assertTrue(extracted.isPresent());
+        assertEquals(NativeTablePolicy.TEXT_ALIGNED_ROW_SELECTED, extracted.orElseThrow().getNativeTablePolicy());
+        assertTrue(extracted.orElseThrow().getPages().values().stream()
+                .flatMap(page -> page.getTables().values().stream())
+                .anyMatch(table -> table.getTotalRows() > 2 && table.getTotalColumns() >= 4));
+    }
+}
